import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, child_id) for child_id in node.get("children", [])]

def scope_nodes(doc, scope_title):
    scope = node_by_title(doc, scope_title)
    if not scope:
        return []
    return children(doc, scope)

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(node["table"]["rows"])]

def entities(doc, scope) -> list:
    entity_dict = {}
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if "Machines" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                mid = row["machine"]
                entity_dict[mid] = f"Machine {mid}"
        elif "Task log" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                tid = row["task"]
                entity_dict[tid] = f"Task {tid}"
    return [{"id": eid, "description": desc} for eid, desc in entity_dict.items()]

def recorded_end(doc, scope) -> float:
    return 1200.0

def inputs(doc, scope) -> list:
    inputs_list = []
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if "Machines" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                mid = row["machine"]
                inputs_list.append({
                    "id": f"input_mach_{mid}_cap",
                    "time": 0.0,
                    "kind": "machine_capacity",
                    "entities": [mid],
                    "fields": {"cpu": int(row["CPU"]), "memory": int(row["memory"])},
                    "src": [[node["node_id"], i]]
                })
                if row["fails at"] != "-":
                    inputs_list.append({
                        "id": f"input_mach_{mid}_fail",
                        "time": float(row["fails at"]),
                        "kind": "machine_failure",
                        "entities": [mid],
                        "fields": {},
                        "src": [[node["node_id"], i]]
                    })
                if row["returns at"] != "-":
                    inputs_list.append({
                        "id": f"input_mach_{mid}_return",
                        "time": float(row["returns at"]),
                        "kind": "machine_return",
                        "entities": [mid],
                        "fields": {},
                        "src": [[node["node_id"], i]]
                    })
        elif "Task log" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                if row["event"] == "submit":
                    tid = row["task"]
                    inputs_list.append({
                        "id": f"input_task_{tid}_submit",
                        "time": float(row["time"]),
                        "kind": "task_submission",
                        "entities": [tid],
                        "fields": {
                            "job": row["job"],
                            "priority": int(row["priority"]),
                            "cpu": int(row["CPU"]),
                            "memory": int(row["memory"]),
                            "run_time": int(row["run time"])
                        },
                        "src": [[node["node_id"], i]]
                    })
    return inputs_list

def outcomes(doc, scope) -> list:
    outcomes_list = []
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if "Task log" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                event = row["event"]
                if event in ["start", "finish", "evict", "fail"]:
                    tid = row["task"]
                    time = float(row["time"])
                    entities_involved = [tid]
                    if row["machine"] != "-":
                        entities_involved.append(row["machine"])
                    outcomes_list.append({
                        "time": time,
                        "kind": f"task_{event}",
                        "entities": entities_involved,
                        "value": None,
                        "src": [[node["node_id"], i]]
                    })
        elif "Events" in node["title"] and node["kind"] == "list":
            for i, line in enumerate(node["lines"]):
                time_match = re.match(r"Time (\d+):", line)
                if not time_match:
                    continue
                time = float(time_match.group(1))
                if "restarted" in line:
                    tid_match = re.search(r"task (T\d+)", line)
                    tid = tid_match.group(1) if tid_match else None
                    outcomes_list.append({"time": time, "kind": "task_restart", "entities": [tid] if tid else [], "value": None, "src": [[node["node_id"], i]]})
                elif "evicted" in line:
                    tids = re.findall(r"task (T\d+)", line)
                    outcomes_list.append({"time": time, "kind": "task_eviction_event", "entities": tids, "value": None, "src": [[node["node_id"], i]]})
                elif "longest wait" in line:
                    wait_match = re.search(r"wait was (\d+)s for task (T\d+)", line)
                    if wait_match:
                        wait_val = int(wait_match.group(1))
                        tid = wait_match.group(2)
                        outcomes_list.append({"time": time, "kind": "longest_wait", "entities": [tid], "value": float(wait_val), "src": [[node["node_id"], i]]})
                elif "stopped" in line:
                    tid_match = re.search(r"task (T\d+)", line)
                    tid = tid_match.group(1) if tid_match else None
                    outcomes_list.append({"time": time, "kind": "task_stopped", "entities": [tid] if tid else [], "value": None, "src": [[node["node_id"], i]]})
        elif "Queue at window end: Tasks running" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "task_running_at_end",
                    "entities": [row["task"]],
                    "value": float(row["remaining"]),
                    "src": [[node["node_id"], i]]
                })
        elif "Queue at window end: Tasks waiting" in node["title"] and node["kind"] == "table":
            for i, row in table_rows(node):
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "task_waiting_at_end",
                    "entities": [row["task"]],
                    "value": None,
                    "src": [[node["node_id"], i]]
                })
    return outcomes_list

def params(doc, scope) -> dict:
    return {"window_length": 1200}



