import collections
import heapq

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    if horizon is None:
        horizon = 1200.0
    if start is None:
        start = 0.0

    # -------------------------------------------------------------------------
    # Data Structures & Initial State
    # -------------------------------------------------------------------------
    # mid -> {cpu, mem, status: 'up'/'down', tasks: set()}
    machines = {} 
    # tid -> {cpu, mem, priority, run_time, submit_time, job}
    tasks_data = {} 
    # tid -> {mid, start_time, end_time}
    running_tasks = {} 
    # queue of tid
    queue = [] 

    sorted_inputs = sorted(inputs, key=lambda x: x['time'])
    pq = [] # Priority Queue for events: (time, type, entity_id)
    # Types: 1: Finish, 2: Failure, 3: Return, 4: Submit

    for inp in sorted_inputs:
        if inp['kind'] == 'machine_capacity':
            mid = inp['entities'][0]
            machines[mid] = {
                'cpu': inp['fields']['cpu'], 
                'mem': inp['fields']['memory'], 
                'status': 'up', 
                'tasks': set()
            }
        elif inp['kind'] == 'machine_failure':
            heapq.heappush(pq, (inp['time'], 2, inp['entities'][0]))
        elif inp['kind'] == 'machine_return':
            heapq.heappush(pq, (inp['time'], 3, inp['entities'][0]))
        elif inp['kind'] == 'task_submission':
            tid = inp['entities'][0]
            tasks_data[tid] = {
                'cpu': inp['fields']['cpu'], 
                'mem': inp['fields']['memory'],
                'priority': inp['fields']['priority'], 
                'run_time': inp['fields']['run_time'],
                'submit_time': inp['time'], 
                'job': inp['fields']['job']
            }
            heapq.heappush(pq, (inp['time'], 4, tid))

    all_outcomes = []

    def get_free_resources(mid, t):
        m = machines[mid]
        used_cpu = 0
        used_mem = 0
        for tid in m['tasks']:
            if tid in running_tasks:
                rt = running_tasks[tid]
                if rt['start_time'] <= t < rt['end_time']:
                    used_cpu += tasks_data[tid]['cpu']
                    used_mem += tasks_data[tid]['mem']
        return m['cpu'] - used_cpu, m['mem'] - used_mem

    def find_earliest_start(mid, tid, t):
        req_cpu = tasks_data[tid]['cpu']
        req_mem = tasks_data[tid]['mem']
        m = machines[mid]
        if req_cpu > m['cpu'] or req_mem > m['mem']:
            return float('inf')

        check_times = {t}
        for tid_r in m['tasks']:
            if tid_r in running_tasks:
                check_times.add(running_tasks[tid_r]['end_time'])

        for ct in sorted(list(check_times)):
            if ct < t: continue
            cpu_f, mem_f = get_free_resources(mid, ct)
            if cpu_f >= req_cpu and mem_f >= req_mem:
                return ct
        return float('inf')

    # -------------------------------------------------------------------------
    # Simulation Loop
    # -------------------------------------------------------------------------
    while pq:
        t = pq[0][0]
        if t > horizon and start is not None:
            # Still process to ensure final states if needed, but we stop at horizon
            pass

        tick_events = []
        while pq and pq[0][0] == t:
            tick_events.append(heapq.heappop(pq))

        # 1. Finishes
        # Tasks whose run time is over finish. Order: by task id.
        finished_now = sorted([tid for tid, info in running_tasks.items() if info['end_time'] == t])
        for tid in finished_now:
            mid = running_tasks[tid]['mid']
            machines[mid]['tasks'].remove(tid)
            if t > start:
                all_outcomes.append({"time": t, "kind": "task_finish", "entities": [tid], "value": None})
            del running_tasks[tid]

        # 2. Failures
        # Machines that fail at this time go down. Order: by machine, then task id.
        failure_events = sorted([ev for ev in tick_events if ev[1] == 2], key=lambda x: x[2])
        for ev in failure_events:
            mid = ev[2]
            machines[mid]['status'] = 'down'
            stopped_tasks = sorted(list(machines[mid]['tasks']))
            for tid in stopped_tasks:
                if t > start:
                    all_outcomes.append({"time": t, "kind": "task_fail", "entities": [tid, mid], "value": None})
                if tid in running_tasks:
                    del running_tasks[tid]
                queue.append(tid)
            machines[mid]['tasks'].clear()

        # 3. Returns
        # Machines that return at this time come back.
        return_events = [ev for ev in tick_events if ev[1] == 3]
        for ev in return_events:
            mid = ev[2]
            machines[mid]['status'] = 'up'

        # 4. Submissions
        # Tasks submitted join the queue. Order: by task id.
        submit_events = sorted([ev for ev in tick_events if ev[1] == 4], key=lambda x: x[2])
        for ev in submit_events:
            tid = ev[2]
            queue.append(tid)

        # 5. Scheduling Round
        # Higher priority first, then earlier submission time, then lower task id.
        queue.sort(key=lambda tid: (-tasks_data[tid]['priority'], tasks_data[tid]['submit_time'], tid))
        reservation = None 

        queue_idx = 0
        while queue_idx < len(queue):
            tid = queue[queue_idx]
            if tid in running_tasks:
                queue_idx += 1
                continue

            task = tasks_data[tid]
            started = False

            # a. First Fit
            for mid in sorted(machines.keys()):
                m = machines[mid]
                if m['status'] == 'down': continue

                if reservation and reservation[0] == mid:
                    res_mid, res_time, res_tid = reservation
                    task_end_time = t + task['run_time']
                    if task_end_time <= res_time:
                        cpu_f, mem_f = get_free_resources(mid, t)
                        if cpu_f >= task['cpu'] and mem_f >= task['mem']:
                            started = True
                    else:
                        # Fit at reserved time check
                        res_cpu = m['cpu'] - tasks_data[res_tid]['cpu']
                        res_mem = m['mem'] - tasks_data[res_tid]['mem']
                        for tid_r in m['tasks']:
                            if tid_r in running_tasks and running_tasks[tid_r]['end_time'] > res_time:
                                res_cpu -= tasks_data[tid_r]['cpu']
                                res_mem -= tasks_data[tid_r]['mem']
                        if res_cpu >= task['cpu'] and res_mem >= task['mem']:
                            cpu_f, mem_f = get_free_resources(mid, t)
                            if cpu_f >= task['cpu'] and mem_f >= task['mem']:
                                started = True
                else:
                    cpu_f, mem_f = get_free_resources(mid, t)
                    if cpu_f >= task['cpu'] and mem_f >= task['mem']:
                        started = True

                if started:
                    machines[mid]['tasks'].add(tid)
                    running_tasks[tid] = {'mid': mid, 'start_time': t, 'end_time': t + task['run_time']}
                    heapq.heappush(pq, (t + task['run_time'], 1, tid))
                    if t > start:
                        all_outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                    queue.remove(tid)
                    queue.sort(key=lambda tid: (-tasks_data[tid]['priority'], tasks_data[tid]['submit_time'], tid))
                    queue_idx = -1
                    break

            if started:
                queue_idx += 1
                continue

            # b. Preemption
            if reservation is None and task['priority'] >= 9:
                preempted = False
                for mid in sorted(machines.keys()):
                    m = machines[mid]
                    if m['status'] == 'down': continue
                    free_tier = [tid_r for tid_r in m['tasks'] if tasks_data[tid_r]['priority'] <= 1]
                    # Order: lowest priority, most recently started, higher task id
                    free_tier.sort(key=lambda tid_r: (tasks_data[tid_r]['priority'], -running_tasks[tid_r]['start_time'], -int(tid_r[1:])))

                    evicted_list = []
                    cpu_f, mem_f = get_free_resources(mid, t)
                    for tid_e in free_tier:
                        cpu_f += tasks_data[tid_e]['cpu']
                        mem_f += tasks_data[tid_e]['mem']
                        evicted_list.append(tid_e)
                        if cpu_f >= task['cpu'] and mem_f >= task['mem']:
                            for tid_ev in evicted_list:
                                if t > start:
                                    all_outcomes.append({"time": t, "kind": "task_evict", "entities": [tid_ev, mid], "value": None})
                                machines[mid]['tasks'].remove(tid_ev)
                                if tid_ev in running_tasks:
                                    del running_tasks[tid_ev]
                                queue.append(tid_ev)
                            machines[mid]['tasks'].add(tid)
                            running_tasks[tid] = {'mid': mid, 'start_time': t, 'end_time': t + task['run_time']}
                            heapq.heappush(pq, (t + task['run_time'], 1, tid))
                            if t > start:
                                all_outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                            queue.remove(tid)
                            preempted = True
                            break
                    if preempted: break

                if preempted:
                    queue.sort(key=lambda tid: (-tasks_data[tid]['priority'], tasks_data[tid]['submit_time'], tid))
                    queue_idx = -1
                    continue

            # c. Reservation
            if reservation is None:
                best_time = float('inf')
                best_mid = None
                for mid in sorted(machines.keys()):
                    if machines[mid]['status'] == 'down': continue
                    t_start = find_earliest_start(mid, tid, t)
                    if t_start < best_time:
                        best_time = t_start
                        best_mid = mid
                if best_mid is not None and best_time != float('inf'):
                    reservation = (best_mid, best_time, tid)

            queue_idx += 1

    return all_outcomes
